sys_ui_action.script:
/* global fetch */
/* global GlideModal */
/* global g_ck, g_form, g_navigation */
/* eslint no-undef: "error" */
function devops_impersonateUser() {
	var gm = new GlideModal('glide_confirm_standard'); 
	gm.setTitle('Confirm Impersonation');
	gm.setPreference('title', 'You are about to impersonate "' + g_form.getValue('name') + '"');
	gm.setPreference('warning', true);
	gm.setPreference('onPromptComplete', function () {
		gm.dev_okPressed = true;
	});
	gm.setPreference('onPromptCancel', function () {
		gm.dev_cancelPressed = true;
	});
	gm.on('closeconfirm', function() {
		var okPressed = !!gm.dev_okPressed;

		// reset state
		delete gm.dev_okPressed;
		delete gm.dev_cancelPressed;

		if (okPressed ) {
			fetch('api/now/ui/impersonate/' + g_form.getUniqueValue(), {
				method: 'POST',
				headers: {
					'X-Usertoken': g_ck
				}
			}).then(function (response) {
				if (response.ok) {
					g_navigation.refreshNavigator();
					g_navigation.reloadWindow();
					return;
				}

				response.text().then(function (text) {
					g_form.addErrorMessage('Failed to impersonate: ' + text);
				});
			});

			return false;
		}
	});
	gm.render();
}
